const carify=b=>b.replace(/<rect x="([\d.]+)" y="([\d.]+)" width="([\d.]+)" height="([\d.]+)" rx="([\d.]+)" fill="(#378ADD|#5F5E5A|#D85A30)"\/>/g,(m,x,y,w,h,rx,c)=>{
  x=+x;y=+y;w=+w;h=+h;const L=Math.max(w,h),S=Math.min(w,h);if(L<26||L>60||S<10||S>36)return m;
  const hor=w>=h,gray=c==='#5F5E5A',body=gray?'#d6d4cc':c,edge=gray?'#4a4a47':'#1d1d1b';let t='';
  const tl=Math.max(5,L*.16),tw=3;
  const wheels=hor?[[x+L*.14,y-tw/2],[x+L*.86-tl,y-tw/2],[x+L*.14,y+h-tw/2],[x+L*.86-tl,y+h-tw/2]].map(([a,b])=>`<rect x="${a}" y="${b}" width="${tl}" height="${tw}" rx="1" fill="#1d1d1b"/>`)
    :[[x-tw/2,y+L*.14],[x-tw/2,y+L*.86-tl],[x+w-tw/2,y+L*.14],[x+w-tw/2,y+L*.86-tl]].map(([a,b])=>`<rect x="${a}" y="${b}" width="${tw}" height="${tl}" rx="1" fill="#1d1d1b"/>`);
  t+=wheels.join('')+`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${Math.max(rx,4)}" fill="${body}" stroke="${edge}" stroke-width="1"/>`;
  const gi=S*.2;t+=hor?`<rect x="${x+L*.3}" y="${y+gi}" width="${L*.4}" height="${h-gi*2}" rx="2" fill="#eaf3fb" opacity=".85"/>`
    :`<rect x="${x+gi}" y="${y+L*.3}" width="${w-gi*2}" height="${L*.4}" rx="2" fill="#eaf3fb" opacity=".85"/>`;
  return '<g>'+t+'</g>'}).replace(/fill="#8a8a86"/g,'fill="#6c6c69"');
'use strict';
